package dev.smpcristalix.pvpcombat.service;
import dev.smpcristalix.pvpcombat.data.PlayerProfile;import net.kyori.adventure.text.*;import net.kyori.adventure.text.format.NamedTextColor;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import java.util.List;
/** GUI только отображает данные; правила прокачки находятся в UpgradeService. */
public final class GuiService{public static final String TITLE="PvPCombat — Прокачка";private final StatsService stats;private final ShardService shards;public GuiService(StatsService s,ShardService h){stats=s;shards=h;}public void open(Player p){Inventory inv=Bukkit.createInventory(null,27,Component.text(TITLE));PlayerProfile x=stats.profile(p.getUniqueId());inv.setItem(10,item(Material.IRON_SWORD,"Урон","Уровень: "+x.damageLevel()));inv.setItem(11,item(Material.RED_DYE,"Здоровье","Сердец: "+String.format("%.1f",stats.healthHearts(x))));inv.setItem(13,item(Material.SUGAR,"Скорость","Уровень: "+x.speedLevel()));inv.setItem(15,item(Material.COOKED_BEEF,"Сытость","Уровень: "+x.satietyLevel()));inv.setItem(16,item(Material.ENCHANTED_BOOK,"Умения","Уровень: "+x.abilityLevel()));inv.setItem(22,item(Material.AMETHYST_SHARD,"Осколки","В инвентаре: "+shards.count(p)));p.openInventory(inv);}private ItemStack item(Material m,String n,String l){ItemStack i=new ItemStack(m);var meta=i.getItemMeta();meta.displayName(Component.text(n,NamedTextColor.LIGHT_PURPLE));meta.lore(List.of(Component.text(l,NamedTextColor.GRAY),Component.text("ЛКМ — улучшить за 1 Осколок",NamedTextColor.DARK_GRAY)));i.setItemMeta(meta);return i;}}
